def circularSums(nums, queries):
    n = len(nums)
    pre = [0]
    for x in nums:
        pre.append(pre[-1] + x)
    total = pre[n]
    out = []
    for start, length in queries:
        laps, rem = divmod(length, n)
        end = start + rem
        if end <= n:
            part = pre[end] - pre[start]
        else:
            part = pre[n] - pre[start] + pre[end - n]
        out.append(laps * total + part)
    return out
